import sys

def parse_input():
    input = sys.stdin.read().splitlines()
    n, m, k = map(int, input[0].split())
    pictures = []
    index = 1
    for _ in range(k + 1):
        picture = [input[i] for i in range(index + 1, index + 1 + n)]
        pictures.append(picture)
        index += n + 1
    return n, m, k, pictures

def can_recolor(picture, x, y):
    target = picture[x][y]
    opposite = '1' if target == '0' else '0'
    return (picture[x - 1][y] == opposite and
            picture[x + 1][y] == opposite and
            picture[x][y - 1] == opposite and
            picture[x][y + 1] == opposite)

def apply_operation(picture, operation):
    if operation[0] == '1':
        _, x, y = operation
        picture[x][y] = '1' if picture[x][y] == '0' else '0'
    elif operation[0] == '2':
        pass

def find_initial_and_operations(n, m, k, pictures):
    from collections import defaultdict
    from itertools import permutations

    def matches(p1, p2):
        return all(p1[i] == p2[i] for i in range(n))

    operations = []
    for perm in permutations(range(k + 1)):
        current_picture = pictures[perm[0]]
        visited = set([perm[0]])
        valid = True
        for i in range(1, k + 1):
            found = False
            for j in range(k + 1):
                if j not in visited:
                    new_picture = [list(row) for row in current_picture]
                    for x in range(1, n - 1):
                        for y in range(1, m - 1):
                            if can_recolor(new_picture, x, y):
                                apply_operation(new_picture, ('1', x, y))
                                operations.append(f"1 {x + 1} {y + 1}")
                                if matches(new_picture, pictures[perm[j]]):
                                    visited.add(perm[j])
                                    current_picture = new_picture
                                    found = True
                                    break
                    if not found:
                        if matches(current_picture, pictures[perm[j]]):
                            visited.add(perm[j])
                            operations.append(f"2 {perm[j] + 1}")
                            found = True
                    if found:
                        break
            if not found:
                valid = False
                break
        if valid:
            return perm[0] + 1, operations
    return -1, []

n, m, k, pictures = parse_input()
initial_index, operations = find_initial_and_operations(n, m, k, pictures)
print(initial_index)
print(len(operations))
for op in operations:
